  on: true, amp: 1.69,
  stiffness: 23,            // ω ≈ 4.8 rad/s — a 0.76 Hz swing. He halved my guess: slower reads heavier
  damping: 2.8,             // ζ ≈ 0.29 — and looser with it, so it keeps travelling
  gain: 1.0,
  max: 0.25,                // he took this to the old ceiling, so the ceiling moved
  axis: [1.0, 0.40, 1.0],   // a card slides sideways and front-to-back; it cannot stretch downward
