  swayTip:{ value: new THREE.Vector3() },
  driftA: { value: new THREE.Vector3() },
  driftB: { value: new THREE.Vector3() },
  pivot:  { value: new THREE.Vector3() },
  ax:     { value: new THREE.Vector3(0, 0, 1) },
  twist:  { value: 0 },
